function mixSamples(a, b, ga, gb){
  ga=(ga==null)?1:ga; gb=(gb==null)?1:gb;
  var n=Math.min(a.length,b.length);
  var out=new Array(n);
  for(var i=0;i<n;i++){ var v=a[i]*ga+b[i]*gb; out[i]=Math.max(-1,Math.min(1,v)); }
  return out;
}
function norm(samples, peak){
  peak=(peak==null)?0.99:peak; var mx=0;
  for(var i=0;i<samples.length;i++){ var a=Math.abs(samples[i]); if(a>mx) mx=a; }
  if(mx===0) return samples.slice();
  var g=peak/mx; return samples.map(function(x){ return Math.max(-1,Math.min(1,x*g)); });
}
var EXPORTS={mixSamples:mixSamples,norm:norm};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AudioMixForgePure = EXPORTS; }
